-- Generated by pnpm db:sql from the lesson frontmatter. Safe to rerun.
BEGIN;
CREATE TABLE IF NOT EXISTS app_users (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  google_sub text NOT NULL UNIQUE,
  email text NOT NULL UNIQUE CHECK (email ~ '^[^@[:space:]]+@snu[.]ac[.]kr$'),
  name text NOT NULL DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now(),
  last_login_at timestamptz NOT NULL DEFAULT now(),
  disabled_at timestamptz
);
CREATE TABLE IF NOT EXISTS learning_items (
  id text PRIMARY KEY,
  week smallint NOT NULL CHECK (week BETWEEN 0 AND 8),
  kind text NOT NULL CHECK (kind IN ('concept','assignment')),
  label text NOT NULL
);
CREATE TABLE IF NOT EXISTS learning_progress (
  user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
  item_id text NOT NULL REFERENCES learning_items(id),
  completed boolean NOT NULL DEFAULT false,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id,item_id)
);
CREATE INDEX IF NOT EXISTS learning_progress_item_completed ON learning_progress(item_id) WHERE completed;
CREATE INDEX IF NOT EXISTS learning_progress_updated ON learning_progress(updated_at DESC);
-- No public/anonymous database role: every app query is made on the server after session authorization.

CREATE TABLE IF NOT EXISTS week_quizzes (
 week smallint PRIMARY KEY CHECK (week BETWEEN 2 AND 8),
 questions jsonb NOT NULL DEFAULT '[]',
 instructions text NOT NULL DEFAULT '',
 password_hash text NOT NULL DEFAULT '',
 published boolean NOT NULL DEFAULT false,
 revision integer NOT NULL DEFAULT 1,
 updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS week_unlocks (
 user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
 week smallint NOT NULL CHECK (week BETWEEN 2 AND 8),
 unlocked_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(user_id,week)
);
CREATE TABLE IF NOT EXISTS quiz_attempts (
 user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
 week smallint NOT NULL CHECK (week BETWEEN 2 AND 8),
 window_start timestamptz NOT NULL DEFAULT now(),
 attempts integer NOT NULL DEFAULT 1,
 PRIMARY KEY(user_id,week)
);
CREATE TABLE IF NOT EXISTS lesson_edits (
 week smallint PRIMARY KEY CHECK (week BETWEEN 0 AND 8),
 body text NOT NULL,
 revision integer NOT NULL DEFAULT 1,
 updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE lesson_edits ADD COLUMN IF NOT EXISTS colab_url text;
-- NULL uses the course notebook. Empty string hides the practice button.

-- Revised curriculum v2. Run inside db/setup.sql's transaction.
-- Keeps users and unlocked weeks. Backs up edits, quizzes and progress first.
CREATE TABLE IF NOT EXISTS curriculum_revisions (revision text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS curriculum_content_archive (revision text NOT NULL, kind text NOT NULL, data jsonb NOT NULL, PRIMARY KEY(revision,kind));
CREATE TABLE IF NOT EXISTS curriculum_progress_archive (
 revision text NOT NULL, user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
 item_id text NOT NULL, completed boolean NOT NULL, updated_at timestamptz NOT NULL,
 PRIMARY KEY(revision,user_id,item_id)
);
INSERT INTO curriculum_content_archive SELECT 'revised-v2','lessons',COALESCE(jsonb_agg(to_jsonb(e)),'[]') FROM lesson_edits e HAVING NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2') ON CONFLICT DO NOTHING;
INSERT INTO curriculum_content_archive SELECT 'revised-v2','quizzes',COALESCE(jsonb_agg(to_jsonb(q)),'[]') FROM week_quizzes q HAVING NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2') ON CONFLICT DO NOTHING;
INSERT INTO curriculum_content_archive SELECT 'revised-v2','items',COALESCE(jsonb_agg(to_jsonb(i)),'[]') FROM learning_items i HAVING NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2') ON CONFLICT DO NOTHING;
INSERT INTO curriculum_progress_archive SELECT 'revised-v2',user_id,item_id,completed,updated_at FROM learning_progress WHERE NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2') ON CONFLICT DO NOTHING;
DELETE FROM learning_progress WHERE NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2');
DELETE FROM learning_items WHERE NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2');
INSERT INTO learning_items(id,week,kind,label)
SELECT id,week,kind,label FROM jsonb_to_recordset('[{"id":"w0:Colab","week":0,"kind":"concept","label":"Colab"},{"id":"w0:Python","week":0,"kind":"concept","label":"Python"},{"id":"w0:Function","week":0,"kind":"concept","label":"Function"},{"id":"w0:List","week":0,"kind":"concept","label":"List"},{"id":"w0:NumPy","week":0,"kind":"concept","label":"NumPy"},{"id":"w0:Shape","week":0,"kind":"concept","label":"Shape"},{"id":"w0:Indexing","week":0,"kind":"concept","label":"Indexing"},{"id":"w0:Vectorized Operation","week":0,"kind":"concept","label":"Vectorized Operation"},{"id":"w0:assignment:Check","week":0,"kind":"assignment","label":"Check"},{"id":"w0:assignment:Apply","week":0,"kind":"assignment","label":"Apply"},{"id":"w0:assignment:Explore","week":0,"kind":"assignment","label":"Explore"},{"id":"w1:Model","week":1,"kind":"concept","label":"Model"},{"id":"w1:Parameter","week":1,"kind":"concept","label":"Parameter"},{"id":"w1:Feature","week":1,"kind":"concept","label":"Feature"},{"id":"w1:Prediction","week":1,"kind":"concept","label":"Prediction"},{"id":"w1:Target","week":1,"kind":"concept","label":"Target"},{"id":"w1:Loss","week":1,"kind":"concept","label":"Loss"},{"id":"w1:Dataset Loss","week":1,"kind":"concept","label":"Dataset Loss"},{"id":"w1:assignment:Check","week":1,"kind":"assignment","label":"Check"},{"id":"w1:assignment:Apply","week":1,"kind":"assignment","label":"Apply"},{"id":"w1:assignment:Explore","week":1,"kind":"assignment","label":"Explore"},{"id":"w2:Vector","week":2,"kind":"concept","label":"Vector"},{"id":"w2:Dot Product","week":2,"kind":"concept","label":"Dot Product"},{"id":"w2:Matrix Multiplication","week":2,"kind":"concept","label":"Matrix Multiplication"},{"id":"w2:Linear Classifier","week":2,"kind":"concept","label":"Linear Classifier"},{"id":"w2:Hyperplane","week":2,"kind":"concept","label":"Hyperplane"},{"id":"w2:Perceptron","week":2,"kind":"concept","label":"Perceptron"},{"id":"w2:assignment:Check","week":2,"kind":"assignment","label":"Check"},{"id":"w2:assignment:Apply","week":2,"kind":"assignment","label":"Apply"},{"id":"w2:assignment:Explore","week":2,"kind":"assignment","label":"Explore"},{"id":"w3:Feature Space","week":3,"kind":"concept","label":"Feature Space"},{"id":"w3:Linear Separability","week":3,"kind":"concept","label":"Linear Separability"},{"id":"w3:Feature Transformation","week":3,"kind":"concept","label":"Feature Transformation"},{"id":"w3:Polynomial Feature","week":3,"kind":"concept","label":"Polynomial Feature"},{"id":"w3:XOR","week":3,"kind":"concept","label":"XOR"},{"id":"w3:assignment:Check","week":3,"kind":"assignment","label":"Check"},{"id":"w3:assignment:Apply","week":3,"kind":"assignment","label":"Apply"},{"id":"w3:assignment:Explore","week":3,"kind":"assignment","label":"Explore"},{"id":"w4:Derivative","week":4,"kind":"concept","label":"Derivative"},{"id":"w4:Partial Derivative","week":4,"kind":"concept","label":"Partial Derivative"},{"id":"w4:Gradient","week":4,"kind":"concept","label":"Gradient"},{"id":"w4:Gradient Descent","week":4,"kind":"concept","label":"Gradient Descent"},{"id":"w4:Learning Rate","week":4,"kind":"concept","label":"Learning Rate"},{"id":"w4:Chain Rule","week":4,"kind":"concept","label":"Chain Rule"},{"id":"w4:Computational Graph","week":4,"kind":"concept","label":"Computational Graph"},{"id":"w4:assignment:Check","week":4,"kind":"assignment","label":"Check"},{"id":"w4:assignment:Apply","week":4,"kind":"assignment","label":"Apply"},{"id":"w4:assignment:Explore","week":4,"kind":"assignment","label":"Explore"},{"id":"w5:Linear Layer","week":5,"kind":"concept","label":"Linear Layer"},{"id":"w5:MLP","week":5,"kind":"concept","label":"MLP"},{"id":"w5:Activation","week":5,"kind":"concept","label":"Activation"},{"id":"w5:Sigmoid","week":5,"kind":"concept","label":"Sigmoid"},{"id":"w5:Tanh","week":5,"kind":"concept","label":"Tanh"},{"id":"w5:ReLU","week":5,"kind":"concept","label":"ReLU"},{"id":"w5:Backpropagation","week":5,"kind":"concept","label":"Backpropagation"},{"id":"w5:Autograd","week":5,"kind":"concept","label":"Autograd"},{"id":"w5:assignment:Check","week":5,"kind":"assignment","label":"Check"},{"id":"w5:assignment:Apply","week":5,"kind":"assignment","label":"Apply"},{"id":"w5:assignment:Explore","week":5,"kind":"assignment","label":"Explore"},{"id":"w6:Logit","week":6,"kind":"concept","label":"Logit"},{"id":"w6:Softmax","week":6,"kind":"concept","label":"Softmax"},{"id":"w6:Cross-Entropy","week":6,"kind":"concept","label":"Cross-Entropy"},{"id":"w6:Mini-batch","week":6,"kind":"concept","label":"Mini-batch"},{"id":"w6:Epoch","week":6,"kind":"concept","label":"Epoch"},{"id":"w6:Optimizer","week":6,"kind":"concept","label":"Optimizer"},{"id":"w6:Train/Validation/Test","week":6,"kind":"concept","label":"Train/Validation/Test"},{"id":"w6:Generalization","week":6,"kind":"concept","label":"Generalization"},{"id":"w6:Overfitting","week":6,"kind":"concept","label":"Overfitting"},{"id":"w6:assignment:Check","week":6,"kind":"assignment","label":"Check"},{"id":"w6:assignment:Apply","week":6,"kind":"assignment","label":"Apply"},{"id":"w6:assignment:Explore","week":6,"kind":"assignment","label":"Explore"},{"id":"w7:Image Tensor","week":7,"kind":"concept","label":"Image Tensor"},{"id":"w7:Convolution","week":7,"kind":"concept","label":"Convolution"},{"id":"w7:Kernel","week":7,"kind":"concept","label":"Kernel"},{"id":"w7:Feature Map","week":7,"kind":"concept","label":"Feature Map"},{"id":"w7:Stride","week":7,"kind":"concept","label":"Stride"},{"id":"w7:Padding","week":7,"kind":"concept","label":"Padding"},{"id":"w7:Channel","week":7,"kind":"concept","label":"Channel"},{"id":"w7:Pooling","week":7,"kind":"concept","label":"Pooling"},{"id":"w7:Receptive Field","week":7,"kind":"concept","label":"Receptive Field"},{"id":"w7:Inductive Bias","week":7,"kind":"concept","label":"Inductive Bias"},{"id":"w7:assignment:Check","week":7,"kind":"assignment","label":"Check"},{"id":"w7:assignment:Apply","week":7,"kind":"assignment","label":"Apply"},{"id":"w7:assignment:Explore","week":7,"kind":"assignment","label":"Explore"},{"id":"w8:Deep Network","week":8,"kind":"concept","label":"Deep Network"},{"id":"w8:Degradation","week":8,"kind":"concept","label":"Degradation"},{"id":"w8:Residual Function","week":8,"kind":"concept","label":"Residual Function"},{"id":"w8:Skip Connection","week":8,"kind":"concept","label":"Skip Connection"},{"id":"w8:Identity Mapping","week":8,"kind":"concept","label":"Identity Mapping"},{"id":"w8:Gradient Path","week":8,"kind":"concept","label":"Gradient Path"},{"id":"w8:Batch Normalization","week":8,"kind":"concept","label":"Batch Normalization"},{"id":"w8:ResNet BasicBlock","week":8,"kind":"concept","label":"ResNet BasicBlock"},{"id":"w8:assignment:Check","week":8,"kind":"assignment","label":"Check"},{"id":"w8:assignment:Apply","week":8,"kind":"assignment","label":"Apply"},{"id":"w8:assignment:Explore","week":8,"kind":"assignment","label":"Explore"}]'::jsonb) AS i(id text,week smallint,kind text,label text)
WHERE NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2') ON CONFLICT(id) DO NOTHING;
-- Match concept labels, moving old weeks 2->4, 3->2, 4->3. New assignments start unchecked.
INSERT INTO learning_progress(user_id,item_id,completed,updated_at)
SELECT p.user_id,n.id,p.completed,p.updated_at
FROM curriculum_progress_archive p
JOIN curriculum_content_archive a ON a.revision=p.revision AND a.kind='items'
CROSS JOIN LATERAL jsonb_to_recordset(a.data) AS old(id text,week smallint,kind text,label text)
JOIN learning_items n ON n.kind='concept' AND n.label=old.label AND n.week=CASE old.week WHEN 2 THEN 4 WHEN 3 THEN 2 WHEN 4 THEN 3 ELSE old.week END
WHERE p.revision='revised-v2' AND p.item_id=old.id AND old.kind='concept' AND NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2')
ON CONFLICT(user_id,item_id) DO NOTHING;
-- Old custom bodies/Colab links remain in the archive. The new source becomes the default.
DELETE FROM lesson_edits WHERE NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2');
DELETE FROM week_quizzes WHERE NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2');
INSERT INTO week_quizzes(week,questions,instructions,password_hash,published,revision,updated_at)
SELECT CASE q.week WHEN 3 THEN 5 WHEN 4 THEN 3 WHEN 5 THEN 4 ELSE q.week END,
q.questions,q.instructions,q.password_hash,
CASE WHEN q.week BETWEEN 3 AND 5 THEN false ELSE q.published END,q.revision+1,now()
FROM curriculum_content_archive a
CROSS JOIN LATERAL jsonb_to_recordset(a.data) AS q(week smallint,questions jsonb,instructions text,password_hash text,published boolean,revision integer)
WHERE a.revision='revised-v2' AND a.kind='quizzes' AND NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2');
DELETE FROM quiz_attempts WHERE week BETWEEN 3 AND 5 AND NOT EXISTS (SELECT 1 FROM curriculum_revisions WHERE revision='revised-v2');
ALTER TABLE lesson_edits ADD COLUMN IF NOT EXISTS content_revision text NOT NULL DEFAULT 'revised-v2';
ALTER TABLE week_quizzes ADD COLUMN IF NOT EXISTS content_revision text NOT NULL DEFAULT 'revised-v2';
INSERT INTO curriculum_revisions(revision) VALUES('revised-v2') ON CONFLICT DO NOTHING;

-- No lesson text or quiz answers in this schema file.
CREATE TABLE IF NOT EXISTS course_originals (
 week smallint PRIMARY KEY CHECK (week BETWEEN 0 AND 8),
 body text NOT NULL CHECK (length(body)>0),
 updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS course_documents (
 name text PRIMARY KEY,
 body text NOT NULL,
 updated_at timestamptz NOT NULL DEFAULT now()
);

-- Bounded storage: four counters per account, no visitor IP addresses stored.
CREATE TABLE IF NOT EXISTS api_rate_limits (
 user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
 bucket text NOT NULL CHECK (bucket IN ('read','write','import','unlock')),
 window_start timestamptz NOT NULL DEFAULT now(),
 attempts integer NOT NULL DEFAULT 1 CHECK (attempts > 0),
 PRIMARY KEY(user_id,bucket)
);

